  `patient_id` bigint NOT NULL,
  `descricao` varchar(500) DEFAULT NULL,
  `concentracao` varchar(255) DEFAULT NULL,
  `gaveta` varchar(255) DEFAULT NULL,
  `nome` varchar(255) NOT NULL,
