  PRIMARY KEY (`medication_id`),
  KEY `FKffc72nft49hvp60wbltvok6t5` (`medicine_box_id`),
  KEY `FK5fjk5flwb24mj7tsjmparf6vd` (`patient_id`),
  CONSTRAINT `FK5fjk5flwb24mj7tsjmparf6vd` FOREIGN KEY (`patient_id`) REFERENCES `tb_patients_info` (`patient_info_id`),
  CONSTRAINT `FKffc72nft49hvp60wbltvok6t5` FOREIGN KEY (`medicine_box_id`) REFERENCES `tb_medicine_box` (`medicine_box_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `tb_consultations` (
  `consultation_date` date DEFAULT NULL,
