  CONSTRAINT `FKe9ve55pq8oi951ccc7bta90gm` FOREIGN KEY (`doctor_id`) REFERENCES `tb_doctors` (`doctor_info_id`),
  CONSTRAINT `FKmhps7hbmxa2048qd3eab16f00` FOREIGN KEY (`patient_id`) REFERENCES `tb_patients_info` (`patient_info_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `tb_exams` (
  `cancellation_date` date DEFAULT NULL,
